def _txt(h): return re.sub(r"\s+", " ", html.unescape(re.sub("<[^>]+>", "", h))).strip()
def answer(t):
    q, a = QA.get(t["id"], (None, None))
    if not q: return None, None
    if not a:
        s = re.split(r'(?<=[.!?])\s+(?=[A-Z0-9“"(])', _txt(t["how"])); a = s[0]
        if len(a.split()) < 22 and len(s) > 1: a += " " + s[1]
    return q, a
